export const uuid=value=>typeof value==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
export const handle=value=>typeof value==='string'&&/^[a-z][a-z0-9_]{2,29}$/.test(value);
export const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function cash(amount){if(!Number.isSafeInteger(amount))return '—';return 'GH₵'+(amount/100).toLocaleString('en-GH',{minimumFractionDigits:2,maximumFractionDigits:2});}
export function parseMoney(value,{max=1000000}={}){if(typeof value!=='string'||!/^\d{1,7}(?:\.\d{0,2})?$/.test(value.trim()))return null;const [whole,fraction='']=value.trim().split('.');const amount=Number(whole)*100+Number(fraction.padEnd(2,'0'));return Number.isSafeInteger(amount)&&amount>0&&amount<=max?amount:null;}
export function nextAmount(value,key){value=typeof value==='string'?value:'';if(key==='back')return value.slice(0,-1);if(key==='clear')return '';if(key==='.')return value.includes('.')?value:(value||'0')+'.';if(!/^[0-9]$/.test(key))return value;const next=value==='0'?key:value+key;if(!/^\d{1,5}(?:\.\d{0,2})?$/.test(next)||Number(next)>10000)return value;return next;}
export function validateAccount(account,userId){if(!account||!uuid(account.id)||account.userId!==userId||!handle(account.handle)||typeof account.displayName!=='string'||account.currency!=='GHS'||account.sandbox!==true||!Number.isSafeInteger(account.balance)||account.balance<0)throw new Error('Lumo could not verify this account. Sign in again.');return account;}
export function validateQuote(intent,quote,now=Date.now()){
  if(intent?.kind!=='merchant'||!uuid(intent.shopId)||quote?.ok!==true||quote.sandbox!==true||quote.currency!=='GHS'||quote.shop?.id!==intent.shopId||quote.shop.accepting!==true||!uuid(quote.merchant?.id)||quote.shop.merchantId!==quote.merchant.id||typeof quote.merchant.name!=='string'||!quote.merchant.name||typeof quote.shop.name!=='string'||!quote.shop.name)throw new Error('This merchant could not be verified. Ask for a fresh Lumo QR.');
  if(Object.hasOwn(intent,'requestId')){const r=quote.request;if(!uuid(intent.requestId)||!r||r.id!==intent.requestId||r.shopId!==intent.shopId||r.status!=='open'||!Number.isSafeInteger(r.amount)||r.amount<1||r.amount>1000000||!Number.isFinite(Date.parse(r.expiresAt))||Date.parse(r.expiresAt)<=now)throw new Error('This fixed request is unavailable. Ask the merchant for a fresh QR.');}
  else if(quote.request!==null)throw new Error('This Shop QR returned conflicting payment details. Ask for a fresh QR.');
  return quote;
}
export function remainingRefund(payment,activity){if(payment?.type!=='merchant_payment'||!Number.isSafeInteger(payment.amount))return 0;if(Number.isSafeInteger(payment.refundableAmount)&&payment.refundableAmount>=0&&payment.refundableAmount<=payment.amount)return payment.refundableAmount;return Math.max(0,payment.amount-activity.filter(r=>r.type==='refund'&&r.originalPaymentId===payment.id).reduce((sum,r)=>sum+(Number.isSafeInteger(r.amount)?r.amount:0),0));}
export function receiptLabel(receipt,accountId){if(receipt.type==='test_funding')return 'Test funds added';if(receipt.type==='box_save')return 'Saved to Money Box';if(receipt.type==='box_withdraw')return 'Money Box withdrawal';if(receipt.type==='group_contribution')return 'Group contribution';if(receipt.type==='group_payout')return 'Group payout';if(receipt.type==='group_refund')return 'Group funds returned';if(receipt.type==='iou_payment')return 'IOU repayment';if(receipt.type==='refund')return 'Merchant refund';if(receipt.type==='merchant_payment')return 'Merchant payment';return receipt.payerAccountId===accountId?`To @${receipt.payeeHandle||receipt.recipientHandle||'lumo'}`:`From @${receipt.payerHandle||'lumo'}`;}
export function safeError(error){const messages={PLAN_CHANGED:'Your Essentials changed on another device. Refresh before saving your edits.',REVISION_CONFLICT:'This record changed on another device. Refresh before saving.',BUDGET_CATEGORY_UNAVAILABLE:'That Essential is no longer active. Refresh and choose a payment source again.',BUDGET_BELOW_SPENT:'An Essential cannot be reduced below what you already spent.',PLAN_PERIOD_LOCKED:'This plan already has spending. Keep its current dates or start the next plan after this period.',MANDATE_QUORUM:'This payout needs more eligible members. Invite enough people and wait for them to accept.',APPROVAL_FORBIDDEN:'You cannot approve your own request, or you were not an eligible member when it was created.',ALREADY_APPROVED:'Your approval is already recorded. Refresh to see the latest result.',GROUP_DEADLINE:'This group’s contribution deadline has passed.',GROUP_BALANCE:'The group must be empty before it can close. Use a governed payout or return the remaining funds.',PENDING_PAYOUT:'Resolve the group’s pending payout before changing membership or closing it.',GROUP_FORBIDDEN:'Only active group members can open this group.',GROUP_CLOSED:'This group is no longer accepting activity.',PARTNER_CODE_INVALID:'That private partner code does not match this approval, or has expired.',PARTNER_APPROVAL_REQUIRED:'Choose your accepted partner and enter their fresh private approval code.',RELEASE_UNAVAILABLE:'This withdrawal approval is unavailable or has expired. Request a fresh approval.',SECRET_REQUIRED:'Re-enter the private approval information for the original request.',IOU_OVERPAYMENT:'Enter no more than this IOU’s remaining amount.',IOU_UNAVAILABLE:'This IOU must be accepted and still open before it can be repaid.',REMINDER_LIMIT:'You can remind this person once per day.',SCHEDULE_INACTIVE:'This schedule is no longer active.',END_CONDITION_REQUIRED:'Choose a maximum number of transfers or an end date.',CURRENT_SESSION:'Use Sign out to end this session. Device management signs out other sessions.',HANDLE_TAKEN:'That handle is already in use. Sign in or choose another.',INVALID_CREDENTIALS:'That handle and password do not match.',CREDENTIALS_INCORRECT:'That handle and password do not match.',ACCOUNT_SETUP_REQUIRED:'Your account setup needs completing. Sign out and create your account again.',REGISTRATION_LIMIT:'Too many attempts. Please try again later.',RATE_LIMITED:'Please wait a little before trying again.',REGISTRATION_UNAVAILABLE:'Account creation is temporarily unavailable. Please try again.',ACCOUNT_REQUIRED:'Your account setup needs completing. Sign out and create your account again.',SESSION_REVOKED:'Your session ended. Sign in again to continue.',PIN_REQUIRED:'That PIN did not match, or payment approval is temporarily locked. Try your transaction PIN again.',PIN_LOCKED:'Payment approval is temporarily locked. Try again in a minute.',AMOUNT_LOCKED:'Pay the exact amount requested by the merchant.',FUNDING_LIMIT:'You have reached the test-funding allowance for this account.',REFUND_EXCEEDS_PAYMENT:'That amount exceeds the remaining original payment.',SHOP_PAUSED:'This shop is not accepting payments right now.',FORBIDDEN:'Your account does not have permission for this action.',ACCOUNT_SUSPENDED:'This account is restricted. Contact the pilot team.',IDEMPOTENCY_MISMATCH:'This reference belongs to different details. Check the saved original request.'};return messages[error?.code]||(error?.name==='LumoClientError'?error.message:'The connection could not complete this request. Please try again.');}
